    "proxy_transport", "proxy_timeout", "proxy_redirect", "proxy_response", "proxy_exit",
    "proxy_region", "proxy_feed", "proxy_baseline", "proxy_budget", "proxy_quarantine",
    "proxy_revision", "proxy_lock",
]

class DiscoveryAccountHealth(BaseModel):
    """One X account of the pool (AC47, AC52): opaque label only, never a cookie, token or username."""
    label: str
    state: Literal["active", "locked", "inactive", "suspect"]
    reason: str | None = None
    last_used: str | None = None
    cookie_age_days: int | None = None   # None: never refreshed through `--refresh-cookies`
    reads_today: int | None = None  # unknown until accounting has begun; missing cap means unlimited
    cap: int | None = None
    rest_until: str | None = None
    ready: bool | None = None      # None: grandfathered/no ready gate
    parse_strikes: int | None = None
    parse_strike_last_at: str | None = None
    proxy_id: str | None = None
    proxy_state: ProxyState | None = None
    proxy_reason: ProxyReason | None = None
    proxy_checked_at: str | None = None
    proxy_quarantine_until: str | None = None
    region: str | None = None
    connection_style: Literal["plain", "curl"] | None = None
    identity_revision: str | None = None

    @field_validator("proxy_id", "identity_revision")
    @classmethod
    def opaque_uuid(cls, value, info):
        if value is not None:
            parsed = UUID(value)
            if str(parsed) != value or (info.field_name == "identity_revision" and parsed.version != 4):
                raise ValueError("invalid opaque identifier")
        return value

    @field_validator("region")
    @classmethod
    def safe_region(cls, value):
        if value is not None and re.fullmatch(r"[A-Z]{2}(?:-[A-Z0-9]{1,3})?", value) is None:
            raise ValueError("invalid region code")
        return value

    @field_validator("proxy_checked_at", "proxy_quarantine_until")
    @classmethod
    def proxy_timestamp(cls, value):
        if value is not None:
            parsed = datetime.fromisoformat(value)
            if parsed.tzinfo is None or parsed.utcoffset().total_seconds() != 0:
                raise ValueError("invalid UTC timestamp")
        return value

    @model_serializer(mode="wrap")
    def serialize_account(self, handler):
        row = handler(self)
        for key in ("reads_today", "cap", "rest_until", "ready", "parse_strikes", "parse_strike_last_at",
                    "proxy_id", "proxy_state", "proxy_reason", "proxy_checked_at", "proxy_quarantine_until",
                    "region", "connection_style", "identity_revision"):
            if row[key] is None:
                row.pop(key)

    snapshot = pool.health()
except x_pool.XPoolStateError:
    health.paused, health.pause_reason, health.pause_until = True, "state_error", None
    return
accounts = []
try:
    for account in snapshot["accounts"]:
        refreshed = _timestamp((ages or {}).get(account["label"]))
        # Only public fields cross this boundary, never private resolver data.
        public = {key: value for key, value in account.items()
                  if key in DiscoveryAccountHealth.model_fields and key != "cookie_age_days"}
        public["cookie_age_days"] = max(0, (now - refreshed).days) if refreshed else None
        try:
            projected = DiscoveryAccountHealth(**public)
        except ValidationError:
            # Refuse the entire proxy tuple: retaining a healthy state with
            # malformed evidence would turn an unknown into a false success.
            legacy = {key: value for key, value in public.items() if key not in _PROXY_ACCOUNT_FIELDS}
            projected = DiscoveryAccountHealth(**legacy, proxy_state="unknown", proxy_reason="proxy_response")
        accounts.append(projected)
except ValidationError:
    # Invalid legacy data makes the complete snapshot unreadable. Never

const PROXY_STATES: Record<string, true> = { direct: true, unknown: true, healthy: true, quarantined: true, blocked: true };
const PROXY_REASONS: Record<string, true> = {
  proxy_config: true, proxy_private: true, proxy_assignment: true, proxy_policy: true, proxy_address: true,
  proxy_transport: true, proxy_timeout: true, proxy_redirect: true, proxy_response: true, proxy_exit: true,
  proxy_region: true, proxy_feed: true, proxy_baseline: true, proxy_budget: true, proxy_quarantine: true,
  proxy_revision: true, proxy_lock: true,
};

function proxyText(a: DiscoveryAccountHealth): string {
  const state = a.proxy_state && Object.prototype.hasOwnProperty.call(PROXY_STATES, a.proxy_state) ? a.proxy_state : UNKNOWN;
  const reason = a.proxy_reason && Object.prototype.hasOwnProperty.call(PROXY_REASONS, a.proxy_reason) ? ` (${a.proxy_reason})` : "";
  const region = a.region && /^[A-Z]{2}(?:-[A-Z0-9]{1,3})?$/.test(a.region) ? a.region : UNKNOWN;
  const style = a.connection_style === "plain" || a.connection_style === "curl" ? a.connection_style : UNKNOWN;
  return `proxy ${state}${reason}, proxy checked ${utc(a.proxy_checked_at ?? null)}, ` +
    `quarantine until ${utc(a.proxy_quarantine_until ?? null)}, region ${region}, connection style ${style}`;
}

export function accountText(a: DiscoveryAccountHealth): string {
  const ready = a.ready == null ? UNKNOWN : a.ready ? "yes" : "no";
  return `${a.label} ${a.state}${a.reason ? ` (${a.reason})` : ""}, ` +
    (a.cookie_age_days == null ? `cookie age ${UNKNOWN}` : `cookie ${a.cookie_age_days} days old`) +
    `, reads today ${n(a.reads_today)} / ${a.cap == null ? "no limit" : n(a.cap)}` +
    `, rest until ${utc(a.rest_until ?? null)}, ready ${ready}, last used ${utc(a.last_used)}` +
    `, parse strikes ${n(a.parse_strikes)}, last strike ${utc(a.parse_strike_last_at ?? null)}, ${proxyText(a)}`;

def _no_duplicate_keys(pairs):
    seen = {}
    for key, value in pairs:
        if key in seen:
            raise QueriesError(f"queries: duplicate key {str(key)[:30]!r}")
        seen[key] = value
    return seen


def load(path: Path | None = None, placed_symbols=None) -> Queries:
    with (path or QUERIES_PATH).open("rb") as stream:
        raw = stream.read(1024 * 1024 + 1)
    if len(raw) > 1024 * 1024:
        raise QueriesError("queries: file exceeds 1 MiB")
    text = raw.decode("utf-8")
    return validate(json.loads(text, object_pairs_hook=_no_duplicate_keys), placed_symbols)

# The X library's required settings (twscrape_reader.REQUIRED_ENV); X refuses to start without them.
$env:TWS_TELEMETRY = '0'
$env:DO_NOT_TRACK = '1'
$env:TWS_LOG_LEVEL = 'WARNING'
$env:TWS_RAISE_WHEN_NO_ACCOUNT = '1'

# Keep global proxy variables out. Bind only a recognized configured backend; Python verifies curl before loading it.
foreach ($name in @('TWS_PROXY', 'HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'SSL_CERT_FILE', 'SSL_CERT_DIR', 'REQUESTS_CA_BUNDLE', 'CURL_CA_BUNDLE')) {
    Remove-Item -Path "Env:$name" -ErrorAction SilentlyContinue
}
$privateQueries = if ($QueriesPath) { $QueriesPath } elseif ($config.CollectorQueriesPath) { [string]$config.CollectorQueriesPath } else { '' }
if ($privateQueries -and -not [System.IO.Path]::IsPathRooted($privateQueries)) { throw 'Collector query path must be absolute.' }
$queriesPath = if ($privateQueries) { $privateQueries } else { Join-Path $config.RepoRoot 'api\data\attention_queries.json' }
$inputStream = [System.IO.File]::OpenRead($queriesPath)
try {
    $bytes = New-Object byte[] (1048576 + 1)
    $count = 0
    while ($count -lt $bytes.Length) {
        $read = $inputStream.Read($bytes, $count, $bytes.Length - $count)
        if ($read -eq 0) { break }
        $count += $read
    }
    if ($count -gt 1048576) { throw 'Collector query file exceeds 1 MiB.' }
    $queries = [System.Text.Encoding]::UTF8.GetString($bytes, 0, $count) | ConvertFrom-Json
} finally {
    $inputStream.Dispose()
}
$hasRouting = $queries.collector.x_proxy_required -eq $true
foreach ($name in @('x_proxy_list_path', 'x_proxy_assignments_path', 'x_proxy_policy_path')) {
    if ($null -ne $queries.collector.$name) { $hasRouting = $true }
}
if ($hasRouting -and -not $privateQueries) {
    throw 'Configured proxy collection requires an explicit private owner-query path.'
}
$styleProperty = $queries.collector.PSObject.Properties['x_connection_style']
$style = if ($null -eq $styleProperty) { 'plain' } else { $styleProperty.Value }
if ($style -cnotin @('plain', 'curl')) { throw 'Invalid x_connection_style; expected plain or curl.' }
$env:TWS_HTTP_BACKEND = if ($style -eq 'curl') { 'curl' } else { 'httpx' }

# SCREENER_ATTENTION_REDDIT_STREAM is inherited as the owner sets it (exactly 1 turns the Reddit stream on).
$stream = if ($env:SCREENER_ATTENTION_REDDIT_STREAM) { $env:SCREENER_ATTENTION_REDDIT_STREAM } else { '(not set: stream off)' }

$collectorArgs = @('run', '--project', 'api', '--frozen', '--group', 'xreader', 'python', '-m', 'api.data.attention_collector',
                   '--queries', $queriesPath)
